begin; select no_plan();
-- More than the former 60-person cap; the oldest matching person must be found.
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at)
select ('710b0000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','beta710b-'||i||'@example.invalid',now(),now(),now() from generate_series(1,72) i;
insert into public.network_memberships(user_id,status)
select id,'active' from auth.users where email like 'beta710b-%@example.invalid' on conflict(user_id) do update set status='active';
insert into public.network_profiles(user_id,display_name,headline,bio,network_roles,status,published_at,suggestable,expertise)
select ('710b0000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Beta '||i,case when i=2 then 'needle_old_member' else 'Synthetic beta profile' end,'A complete synthetic biography for closed beta verification.',array['founder'],'active',now()-make_interval(days=>case when i=2 then 100 else i end),i<5,array['software'] from generate_series(1,72) i;
update public.network_profiles set location_region='Berlin',remote_mode='remote' where user_id='710b0000-0000-4000-8000-000000000002';
update public.network_profiles set published_at=now() where user_id in('710b0000-0000-4000-8000-000000000003','710b0000-0000-4000-8000-000000000004');
insert into public.network_listings(id,owner_user_id,direction,category,title,summary,status,published_at,expires_at) values('710b0000-0000-4000-8000-000000000100','710b0000-0000-4000-8000-000000000002','offering','expertise','Old eligible listing','A sufficiently long synthetic description.','active',now()-interval '10 days',now()+interval '40 days');
insert into public.network_problems(id,author_user_id,title,description,author_intent,status,published_at) values('710b0000-0000-4000-8000-000000000101','710b0000-0000-4000-8000-000000000003','Synthetic beta problem','A sufficiently long synthetic description of a problem.','observation','active',now());
update public.network_problems set topics=array['beta_problem_only'] where id='710b0000-0000-4000-8000-000000000101';
insert into public.network_ventures(id,owner_user_id,name,what_it_does,audience,status) values('710b0000-0000-4000-8000-000000000102','710b0000-0000-4000-8000-000000000004','Beta project','We build a sufficiently descriptive synthetic needle_venture example for teams.','A sufficiently long target audience description.','active');
-- Ineligible newer rows must not crowd an eligible older listing out of highlights.
insert into public.network_listings(owner_user_id,direction,category,title,summary,status,published_at,expires_at)
select ('710b0000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'seeking','expertise','New ineligible listing','A sufficiently long synthetic description.','active',now(),now()+interval '60 days' from generate_series(5,39) i;
alter table public.network_profiles disable trigger a0_connect_beta_visibility; update public.network_profiles set visibility='public' where user_id='710b0000-0000-4000-8000-000000000002'; alter table public.network_profiles enable trigger a0_connect_beta_visibility;
alter table public.network_listings disable trigger a0_connect_beta_visibility; update public.network_listings set visibility='public' where id='710b0000-0000-4000-8000-000000000100'; alter table public.network_listings enable trigger a0_connect_beta_visibility;
alter table public.network_problems disable trigger a0_connect_beta_visibility; update public.network_problems set visibility='public' where id='710b0000-0000-4000-8000-000000000101'; alter table public.network_problems enable trigger a0_connect_beta_visibility;
create temp table slugs as select (select public_slug from public.network_profiles where user_id='710b0000-0000-4000-8000-000000000002') profile, (select public_slug from public.network_listings where title='Old eligible listing') listing, (select public_slug from public.network_problems where title='Synthetic beta problem') problem; grant select on slugs to anon,authenticated;
reset role; select set_config('request.jwt.claim.sub','',true); set local role anon;
select is((select count(*) from public.get_public_network_profile((select profile from slugs))),0::bigint,'anon no profile, even public-marked');
select is((select count(*) from public.get_public_network_listing((select listing from slugs))),0::bigint,'anon no listing, even public-marked');
select is((select count(*) from public.get_public_network_problem((select problem from slugs))),0::bigint,'anon no problem, even public-marked');
select is((select count(*) from public.list_public_network_profile_listings((select profile from slugs))),0::bigint,'anon no related public objects');
select is((select count(*) from public.list_public_network_profile_ventures((select profile from slugs))),0::bigint,'anon no related public objects');
select is(public.get_public_network_profile_linkedin((select profile from slugs)),null::text,'anon no LinkedIn'); select is((select count(*) from public.list_public_network_sitemap()),0::bigint,'no CONNECT sitemap');
select throws_ok($$select * from public.network_profiles$$,'42501',null,'anon no direct profile read');
select throws_ok($$select * from public.network_listings$$,'42501',null,'anon no direct listing read');
select throws_ok($$select * from public.network_problems$$,'42501',null,'anon no direct problem read');
select throws_ok($$select * from public.search_connect_people()$$,'42501',null,'anon no search RPC');
select throws_ok($$select * from public.list_connect_highlight_candidates('person')$$,'42501',null,'anon no highlight RPC');
select throws_ok($$select * from public.connect_suggestions$$,'42501',null,'anon no suggestions');

reset role; select set_config('request.jwt.claim.sub','710b0000-0000-4000-8000-000000000001',true); set local role authenticated;
select is((select count(*) from public.network_listings where id='710b0000-0000-4000-8000-000000000100'),1::bigint,'member still reads previously public network_listings');
select is((select count(*) from public.network_problems where id='710b0000-0000-4000-8000-000000000101'),1::bigint,'member still reads previously public network_problems');
select is((select count(*) from public.network_profiles where user_id='710b0000-0000-4000-8000-000000000002'),1::bigint,'member still reads previously public network_profiles');
select is((select count(*) from public.list_public_network_sitemap()),0::bigint,'member cannot use public sitemap either');
select is((select count(*) from public.search_connect_people('needle_old_member')),1::bigint,'search reaches beyond old first 60');
select is((select user_id from public.search_connect_people('needle_venture')),'710b0000-0000-4000-8000-000000000004'::uuid,'authorized venture search');
select is((select count(*) from public.search_connect_people('', 'expert','software','','','remote')),0::bigint,'combined filters apply before limit');
select is((select count(*) from public.search_connect_people('needle_old_member','founder','software','','Berlin','remote')),1::bigint,'combined positive filters reach older matching profile');
select is((select array_agg(user_id) from (select user_id from public.search_connect_people() limit 2) p),array['710b0000-0000-4000-8000-000000000003'::uuid,'710b0000-0000-4000-8000-000000000004'::uuid],'equal publication timestamps use stable UUID order');
select is((select count(*) from public.search_connect_people()),25::bigint,'bounded lookahead');
select is((select count(*) from (select user_id from public.search_connect_people() limit 24) a join public.search_connect_people(p_offset=>24) b using(user_id)),0::bigint,'pages do not overlap');
select is((select count(*) from public.list_connect_highlight_candidates('listing') j where j->>'id'='710b0000-0000-4000-8000-000000000100'),1::bigint,'eligible older listing survives 35 ineligible newer rows');
select is((select count(*) from public.list_connect_highlight_candidates('listing')),1::bigint,'consent filtered before window');
select is((select count(*) from public.list_connect_highlight_candidates('problem')),1::bigint,'problem highlight');
insert into public.network_profiles(user_id) values('710b0000-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.network_listings(id,owner_user_id,direction,category,title,summary) values('710b0000-0000-4000-8000-000000000110','710b0000-0000-4000-8000-000000000001','seeking','expertise','Complete draft','A sufficiently long synthetic description.');
insert into public.network_listings(id,owner_user_id,direction,category,title,summary) values('710b0000-0000-4000-8000-000000000111','710b0000-0000-4000-8000-000000000001','seeking','expertise','X','A sufficiently long synthetic description.');
insert into public.network_listings(id,owner_user_id,direction,category,title,summary) values('710b0000-0000-4000-8000-000000000112','710b0000-0000-4000-8000-000000000001','seeking','expertise','Valid draft','Short');
select lives_ok($$select public.transition_connect_content('listing','710b0000-0000-4000-8000-000000000110','publish','draft',true)$$,'complete draft publishes'); select is((select status from public.network_listings where id='710b0000-0000-4000-8000-000000000110'),'active','published active');
select throws_ok($$select public.transition_connect_content('listing','710b0000-0000-4000-8000-000000000111','publish','draft',true)$$,'23514','listing_title_required','specific publication precondition'); select is((select status from public.network_listings where id='710b0000-0000-4000-8000-000000000111'),'draft','failure retains draft');
select throws_ok($$select public.transition_connect_content('listing','710b0000-0000-4000-8000-000000000112','publish','draft',true)$$,'23514','listing_summary_required','specific publication precondition'); select is((select status from public.network_listings where id='710b0000-0000-4000-8000-000000000112'),'draft','failure retains draft');
select throws_ok($$select public.transition_connect_content('listing','710b0000-0000-4000-8000-000000000100','delete','active',true)$$,'40001',null,'foreign lifecycle forbidden');
update public.network_profiles set visibility='public' where user_id='710b0000-0000-4000-8000-000000000001'; select is((select visibility from public.network_profiles where user_id='710b0000-0000-4000-8000-000000000001'),'members_only','new public intent cannot accumulate during beta');
reset role;
insert into public.connect_suggestions(id,recipient_user_id,subject_owner_user_id,person_user_id,matched_terms) values('710b0000-0000-4000-8000-000000000120','710b0000-0000-4000-8000-000000000001','710b0000-0000-4000-8000-000000000002','710b0000-0000-4000-8000-000000000002',array['software']);
insert into public.connect_suggestions(id,recipient_user_id,subject_owner_user_id,listing_id,matched_terms) values('710b0000-0000-4000-8000-000000000121','710b0000-0000-4000-8000-000000000001','710b0000-0000-4000-8000-000000000002','710b0000-0000-4000-8000-000000000100',array['software']);
insert into public.connect_suggestions(id,recipient_user_id,subject_owner_user_id,problem_id,matched_terms) values('710b0000-0000-4000-8000-000000000122','710b0000-0000-4000-8000-000000000001','710b0000-0000-4000-8000-000000000003','710b0000-0000-4000-8000-000000000101',array['software']);
insert into public.connect_suggestions(id,recipient_user_id,subject_owner_user_id,venture_id,matched_terms) values('710b0000-0000-4000-8000-000000000123','710b0000-0000-4000-8000-000000000001','710b0000-0000-4000-8000-000000000004','710b0000-0000-4000-8000-000000000102',array['software']);
reset role; select set_config('request.jwt.claim.sub','710b0000-0000-4000-8000-000000000001',true); set local role authenticated;
select is((select count(*) from public.connect_suggestions),4::bigint,'four available suggestions');
reset role; update public.network_profiles set suggestable=false where user_id='710b0000-0000-4000-8000-000000000002';
reset role; select set_config('request.jwt.claim.sub','710b0000-0000-4000-8000-000000000001',true); set local role authenticated;
select is((select count(*) from public.connect_suggestions where person_user_id='710b0000-0000-4000-8000-000000000002'),0::bigint,'old person suggestion disappears after opt-out'); select is((select count(*) from public.search_connect_people('needle_old_member')),1::bigint,'ordinary search unaffected by opt-out');
reset role; insert into public.network_blocks(blocker_user_id,blocked_user_id) values('710b0000-0000-4000-8000-000000000002','710b0000-0000-4000-8000-000000000001');
reset role; select set_config('request.jwt.claim.sub','710b0000-0000-4000-8000-000000000001',true); set local role authenticated;
select is((select count(*) from public.connect_suggestions),2::bigint,'reverse block removes related suggestions'); select is((select count(*) from public.search_connect_people('needle_old_member')),0::bigint,'reverse block removes search result'); select is((select count(*) from public.list_connect_highlight_candidates('listing')),1::bigint,'only own newly published listing remains after block');
reset role; delete from public.network_blocks where blocker_user_id='710b0000-0000-4000-8000-000000000002'; insert into public.network_blocks(blocker_user_id,blocked_user_id) values('710b0000-0000-4000-8000-000000000001','710b0000-0000-4000-8000-000000000003');
reset role; select set_config('request.jwt.claim.sub','710b0000-0000-4000-8000-000000000001',true); set local role authenticated;
select is((select count(*) from public.list_connect_highlight_candidates('problem')),0::bigint,'forward block removes problem highlight');
reset role; delete from public.network_blocks where blocker_user_id='710b0000-0000-4000-8000-000000000001'; update public.network_listings set expires_at=now()-interval '1 day' where id='710b0000-0000-4000-8000-000000000100'; update public.network_profiles set status='paused' where user_id='710b0000-0000-4000-8000-000000000003';
reset role; select set_config('request.jwt.claim.sub','710b0000-0000-4000-8000-000000000001',true); set local role authenticated;
select is((select count(*) from public.connect_suggestions),1::bigint,'expired listing and paused owner unavailable');
reset role; update public.network_ventures set status='hidden' where id='710b0000-0000-4000-8000-000000000102';
reset role; select set_config('request.jwt.claim.sub','710b0000-0000-4000-8000-000000000001',true); set local role authenticated;
select is((select count(*) from public.connect_suggestions),0::bigint,'hidden venture unavailable');
-- Problem generation must independently require a currently active owner profile.
reset role;
update public.network_profiles set expertise=array['beta_problem_only'] where user_id='710b0000-0000-4000-8000-000000000072';
select set_config('request.jwt.claim.sub','710b0000-0000-4000-8000-000000000072',true);
select is(public.generate_connect_suggestions_for('710b0000-0000-4000-8000-000000000072',3),0,'paused problem owner never generated');
update public.network_profiles set status='active' where user_id='710b0000-0000-4000-8000-000000000003';
select is(public.generate_connect_suggestions_for('710b0000-0000-4000-8000-000000000072',3),1,'active problem owner can generate');
select set_config('request.jwt.claim.sub','710b0000-0000-4000-8000-000000000001',true);
update public.network_problems set moderation_blocked=true where id='710b0000-0000-4000-8000-000000000101';
set local role authenticated;
select is((select count(*) from public.list_connect_highlight_candidates('problem')),0::bigint,'moderation excludes highlight');
select is((select count(*) from public.connect_suggestions where problem_id='710b0000-0000-4000-8000-000000000101'),0::bigint,'moderation excludes old suggestion');
reset role;
update public.network_problems set moderation_blocked=false,status='withdrawn' where id='710b0000-0000-4000-8000-000000000101';
set local role authenticated;
select is((select count(*) from public.connect_suggestions where problem_id='710b0000-0000-4000-8000-000000000101'),0::bigint,'withdrawn problem excludes suggestion');
select is((select count(*) from public.connect_discovery_problems where id='710b0000-0000-4000-8000-000000000101'),0::bigint,'withdrawn problem excludes browse');
reset role; update public.network_profiles set status='active',suggestable=true where user_id='710b0000-0000-4000-8000-000000000002'; update public.network_listings set expires_at=now()+interval '30 days' where id='710b0000-0000-4000-8000-000000000100'; update public.connect_suggestions set dismissed_at=null,notified_at=null where id in('710b0000-0000-4000-8000-000000000120','710b0000-0000-4000-8000-000000000121');
select set_config('request.jwt.claim.sub','',true); set local role service_role; select lives_ok($$select * from public.prepare_suggestion_notifications(200)$$,'notification preparation uses current eligibility');
select is(public.count_connect_notification_delivery('710b0000-0000-4000-8000-000000000001',now()-interval '1 minute'),(select count(*)::int from public.connect_suggestions s where recipient_user_id='710b0000-0000-4000-8000-000000000001' and notified_at>=now()-interval '1 minute' and public.connect_suggestion_eligible(s)),'delivery rechecks eligibility');
select is(public.count_connect_notification_delivery('710b0000-0000-4000-8000-000000000001',now()-interval '1 minute'),2,'only two currently available subjects can notify');
-- A block added after notification claim also prevents delivery.
reset role; insert into public.network_blocks(blocker_user_id,blocked_user_id) values('710b0000-0000-4000-8000-000000000002','710b0000-0000-4000-8000-000000000001');
set local role service_role;
select is(public.count_connect_notification_delivery('710b0000-0000-4000-8000-000000000001',now()-interval '1 minute'),0,'reverse block after claim prevents notification');
reset role; delete from public.network_blocks where blocker_user_id='710b0000-0000-4000-8000-000000000002';
reset role; update public.network_memberships set status='suspended' where user_id='710b0000-0000-4000-8000-000000000001'; select set_config('request.jwt.claim.sub','',true); set local role service_role; select is(public.count_connect_notification_delivery('710b0000-0000-4000-8000-000000000001',now()-interval '1 minute'),0,'suspended recipient cannot be notified');
reset role; select set_config('request.jwt.claim.sub','710b0000-0000-4000-8000-000000000001',true); set local role authenticated;
select is((select count(*) from public.search_connect_people()),0::bigint,'suspended viewer no discovery'); select is((select count(*) from public.connect_discovery_problems),0::bigint,'suspended viewer no problem browse');
reset role; select * from finish(); rollback;
